{
  "criteria": [
    {
      "id": "C1",
      "level": "Adequate",
      "mark": 6,
      "evidence": [
        {
          "where": "Introduction",
          "quote": "Thus, only one satellite is required."
        },
        {
          "where": "Introduction",
          "quote": "The proposed satellite would likely be used by governmental and science agencies (e.g. CSIRO, BOM) for research and/or education."
        },
        {
          "where": "Executive Summary",
          "quote": "The satellite, nicknamed ZYZZsat (Z-axis/Y-axis Zeroed Zoning Satellite), is operated and accessed from Australia ground facilities"
        }
      ],
      "reasoning": "The reef-monitoring purpose, Australian benefit, rationale for one spacecraft, and likely science/government customers are explained. The discussion of bleaching and monitoring need is detailed. However, no specific organisation is identified as the spacecraft operator, and the customer/operator roles remain vague."
    },
    {
      "id": "C2",
      "level": "Adequate",
      "mark": 5,
      "evidence": [
        {
          "where": "Launch",
          "quote": "the proposed satellite will thus use the Vega E rocket as a launch vehicle – launched from the Guiana Space Centre Spaceport."
        },
        {
          "where": "Orbit",
          "quote": "an altitude of 600km requires a mean inclination of $ 97.7924^{\\circ} $ for the satellite to remain sun-synchronous."
        },
        {
          "where": "Ground Control & Communications",
          "quote": "An average contact duration of almost ten minutes was achieved, in addition to the already frequent amount of passes."
        },
        {
          "where": "Mission Duration & EOL",
          "quote": "A span of five years is a sound estimate of the useful lifespan of the proposed satellite."
        },
        {
          "where": "Image 1",
          "quote": ""
        }
      ],
      "reasoning": "The report covers launch, orbit, ground access, duration, and disposal, with STK images and access results. The orbital inclination is plausible for a 600 km sun-synchronous orbit. However, payload capability and reef imaging performance are not established; the local-time-of-node assumption is missing; ground-station compatibility is unverified; and the drag-sail disposal performance is not quantified. STK project files are not provided in the submission."
    },
    {
      "id": "C3",
      "level": "Adequate",
      "mark": 5,
      "evidence": [
        {
          "where": "Conclusion",
          "quote": "A polar sun-synchronous orbit allows for consistent illumination of the oceans while maintaining a constant sun angle."
        },
        {
          "where": "Conclusion",
          "quote": "The Mt Pleasant Radio Observatory is well-located to receive data from this orbit type constantly and for long durations."
        }
      ],
      "reasoning": "The conclusion recaps the selected launch, orbit, and ground facility and relates the mission to reef protection. It is relevant, but mostly summarizes earlier choices rather than drawing detailed conclusions from demonstrated imaging or operational performance."
    },
    {
      "id": "C4",
      "level": "Adequate",
      "mark": 4,
      "evidence": [
        {
          "where": "Executive Summary",
          "quote": "This report outlines the intended designs and procedures involved in the construction of a Earth observation satellite"
        },
        {
          "where": "Image 4",
          "quote": ""
        },
        {
          "where": "Bibliography",
          "quote": "https://en.wikipedia.org/wiki/2021_in_spaceflight."
        }
      ],
      "reasoning": "The report has a recognisable engineering structure, executive summary, headings, conclusion, and bibliography, and the figures support the discussion. Presentation is not fully professional: figures and tables lack consistent numbered captions, several text and grammar issues remain, the bibliography entries are incomplete, and table citations such as [49]–[74] do not match the listed references. Wikipedia is also used despite the task disallowing it."
    }
  ],
